import json, os
from openpyxl import load_workbook

def find_targets(start):
    hits = []
    for root, dirs, files in os.walk(start):
        dirs[:] = [d for d in dirs if d not in (".git", "__pycache__", ".codex")]
        for f in files:
            if f.lower() == "budget.xlsx":
                hits.append(os.path.join(root, f))
    return hits

def dump(path):
    wb_f = load_workbook(path, data_only=False)
    wb_v = load_workbook(path, data_only=True)
    out = {"file": path, "sheets": []}
    for name in wb_f.sheetnames:
        ws_f = wb_f[name]
        ws_v = wb_v[name]
        rows = []
        for row in ws_f.iter_rows():
            entry = {}
            for c in row:
                if c.value is None:
                    continue
                raw = c.value
                if isinstance(raw, str) and raw.startswith("="):
                    cached = ws_v[c.coordinate].value
                    entry[c.coordinate] = {"formula": raw, "cached": cached}
                else:
                    entry[c.coordinate] = raw
            if entry:
                rows.append(entry)
        out["sheets"].append({"name": name, "dims": ws_f.dimensions, "rows": rows})
    return out

hits = find_targets(os.getcwd())
print(json.dumps({"candidates": hits}, default=str))
for h in hits:
    print(json.dumps(dump(h), default=str))

import sys
import json
from datetime import date, datetime, time
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

def norm(v):
    return "" if v is None else str(v).strip().lower()

def to_number(v):
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(",", "").replace("$", "").replace(" ", "")
        if s.startswith("(") and s.endswith(")"):
            s = "-" + s[1:-1]
        try:
            return float(s)
        except ValueError:
            return None
    return None

def js(v):
    if isinstance(v, (datetime, date, time)):
        return v.isoformat()
    return v

path = sys.argv[1]
wb = load_workbook(path, data_only=True)
wbf = load_workbook(path, data_only=False)

report = {"sheets": wb.sheetnames, "contents": {}, "formula_cells": [], "column_sums": {}}

for ws in wb.contents if hasattr(wb, "contents") else wb.worksheets:
    ws = wb[ws.title] if hasattr(wb, "contents") else ws
    sheet = wb[ws.title]
    sheetf = wbf[ws.title]
    rows = list(sheet.iter_rows())
    contents = []
    for row in rows:
        for c in row:
            if c.value is not None:
                contents.append([c.coordinate, js(c.value)])
    report["contents"][sheet.title] = contents
    fv = sheetf[sheetf.calculate_dimension()] if False else None
    for rowf in sheetf.iter_rows():
        for c in rowf:
            if isinstance(c.value, str) and c.value.startswith("="):
                report["formula_cells"].append(c.coordinate + " -> " + c.value)
    grid = [[c.value for c in row] for row in sheet.iter_rows()]
    sums = {}
    if grid:
        ncols = max(len(r) for r in grid)
        for j in range(ncols):
            col_total = 0.0
            has_num = False
            for r in grid:
                val = to_number(r[j]) if j < len(r) else None
                if val is not None:
                    col_total += val
                    has_num = True
            if has_num:
                sums[get_column_letter(j + 1)] = round(col_total, 2)
    report["column_sums"][sheet.title] = sums

print("REPORT=" + json.dumps(report, default=js))

